    for (let j = 0; j < sites.length && cell.length >= 3; j++) {
      if (i === j) continue;
      const t = sites[j];
      cell = clipHalf(cell, t[0] - s[0], t[1] - s[1], (t[0] * t[0] + t[1] * t[1] - s[0] * s[0] - s[1] * s[1]) / 2);
    }
    if (cell.length >= 3 && Math.abs(polyArea(cell)) > 2e-4) cells.push(cell);
  }
