}

// ============================================================ track environment (static, merged)
function buildEnvironment(Lo) {
  const grp = new THREE.Group();
  const bag = new GeoBag();
  const colliders = [];
  const { x0, x1, runoffEnd, zB } = Lo;

  bag.add(M.grass, planeXZ(-420, 420, -420, 420, 0.16, -0.012));
  bag.add(M.asphalt, planeXZ(x0 - 9, x1, -5, 5, 1 / 7, 0));
  bag.add(M.gravel, planeXZ(x1, runoffEnd + 1.6, -zB, zB, 1 / 2.5, -0.004));

  let ci = 0;
  for (let x = x0 - 9; x < x1 - 0.01; x += 1, ci++) {
    const xe = Math.min(x + 1, x1);
    for (const s of [1, -1]) bag.add(M.curb, colorize(boxGeo(x, xe, -0.004, 0.03, s * 5.0, s * 5.85), ci % 2 ? 0xededed : 0xc41e25));
  }
  for (const s of [1, -1]) bag.add(M.line, planeXZ(x0 - 9, x1, s * 4.72 - 0.07, s * 4.72 + 0.07, 1, 0.003));
  for (let x = x0 - 6; x < x1 - 3; x += 6) bag.add(M.line, planeXZ(x, x + 3, -0.06, 0.06, 1, 0.003));
  const zc = Lo.carZ, r0 = Lo.carRear - 0.45, f0 = Lo.carRear + Lo.carLen + 0.45, hw = Lo.carWid / 2 + 0.45;
  bag.add(M.line, planeXZ(r0 - 0.1, r0, zc - hw, zc + hw, 1, 0.0032));
  bag.add(M.line, planeXZ(r0, f0, zc + hw - 0.1, zc + hw, 1, 0.0032));
  bag.add(M.line, planeXZ(r0, f0, zc - hw, zc - hw + 0.1, 1, 0.0032));
  const q = 0.25;
  for (let j = 0; j < 2; j++) for (let i = 0; i < 40; i++) if ((i + j) % 2 === 0) bag.add(M.line, planeXZ(Lo.startLine + j * q, Lo.startLine + (j + 1) * q, -5 + i * q, -5 + (i + 1) * q, 1, 0.0034));

  const bxA = x0 - 12, bxB = runoffEnd + 1.3;
  for (const s of [1, -1]) {
    const zr = s * zB;
    bag.add(M.steel, boxGeo(bxA, bxB, 0.40, 0.56, zr - 0.03, zr + 0.03));
    bag.add(M.steel, boxGeo(bxA, bxB, 0.58, 0.74, zr - 0.03, zr + 0.03));
    bag.add(M.darkSteel, boxGeo(bxA, bxB, 0.555, 0.585, zr - 0.02, zr + 0.02));
    for (let x = bxA; x <= bxB; x += 2) bag.add(M.darkSteel, boxGeo(x - 0.05, x + 0.05, 0, 0.72, zr + s * 0.09 - 0.05, zr + s * 0.09 + 0.05));
    colliders.push({ c: [(bxA + bxB) / 2, 0.45, zr + s * 0.03], h: [(bxB - bxA) / 2, 0.45, 0.08] });
  }
  let ti = 0;
  for (let z = -zB + 0.3; z <= zB - 0.3; z += 0.62) {
    for (let row = 0; row < 2; row++) for (let h = 0; h < 3; h++, ti++) {
      const g = new THREE.CylinderGeometry(0.3, 0.3, 0.24, 18, 1);
      g.translate(runoffEnd + 0.32 + row * 0.6, 0.12 + h * 0.245, z + (row ? 0.31 : 0));
      bag.add(h === 2 && ti % 2 === 0 ? M.white : M.rubber, g);
    }
  }
  colliders.push({ c: [runoffEnd + 0.62, 0.38, 0], h: [0.64, 0.38, zB] });

  const gx = Lo.startLine + 2.2;
  for (const s of [1, -1]) bag.add(M.darkSteel, boxGeo(gx - 0.16, gx + 0.16, 0, 5.7, s * 6.2, s * 6.55));
  bag.add(M.darkSteel, boxGeo(gx - 0.28, gx + 0.28, 5.05, 5.7, -6.55, 6.55));
  bag.add(M.trim, boxGeo(gx - 0.36, gx - 0.28, 5.08, 5.62, -1.7, 1.7));
  for (let i = 0; i < 5; i++) {
    const g = new THREE.CylinderGeometry(0.16, 0.16, 0.05, 20); g.rotateZ(Math.PI / 2); g.translate(gx - 0.385, 5.35, -1.2 + i * 0.6);
    bag.add(M.startLight, g);
  }

  for (const xt of [x0 + 3, x0 + (x1 - x0) * 0.45, x1 - 2, runoffEnd - 3]) {
    const zt = -(zB + 5);
    const g = new THREE.CylinderGeometry(0.12, 0.2, 15, 12); g.translate(xt, 7.5, zt); bag.add(M.darkSteel, g);
    bag.add(M.trim, boxGeo(xt - 1.4, xt + 1.4, 14.2, 15.6, zt - 0.2, zt + 0.2));
    for (let i = 0; i < 4; i++) for (let j = 0; j < 2; j++) bag.add(M.flood, boxGeo(xt - 1.25 + i * 0.65, xt - 0.8 + i * 0.65, 14.35 + j * 0.65, 14.85 + j * 0.65, zt + 0.2, zt + 0.24));
  }

  const gz0 = -(zB + 14), gxA = x0 - 4, gxB = x1 + 8;
  for (let k = 0; k < 7; k++) {
    bag.add(M.concrete, boxGeo(gxA, gxB, 0, 0.9 * (k + 1), gz0 - k * 1.6 - 1.6, gz0 - k * 1.6));
    bag.add(M.seatBlue, boxGeo(gxA + 0.3, gxB - 0.3, 0.9 * (k + 1), 0.9 * (k + 1) + 0.3, gz0 - k * 1.6 - 0.75, gz0 - k * 1.6 - 0.25));
  }
  bag.add(M.steel, boxGeo(gxA - 1, gxB + 1, 9.4, 9.7, gz0 - 12.5, gz0 + 1.2));
  for (let x = gxA; x <= gxB; x += 8) bag.add(M.darkSteel, boxGeo(x - 0.15, x + 0.15, 0, 9.4, gz0 - 12.2, gz0 - 11.9));

  const pz = zB + 26;
  bag.add(M.concrete, boxGeo(x0 - 5, x0 + 50, 0, 7, pz, pz + 12));
  bag.add(M.winGlass, boxGeo(x0 - 4.5, x0 + 49.5, 2.8, 5.8, pz - 0.02, pz + 0.05));
  bag.add(M.white, boxGeo(x0 - 5.5, x0 + 50.5, 7, 7.5, pz - 0.6, pz + 12.4));

  const tr = mulberry32(99);
  for (let i = 0; i < 150; i++) {
    const a = tr() * Math.PI * 2, r = 115 + tr() * 170;
    const x = 5 + Math.cos(a) * r, z = Math.sin(a) * r, h = 7 + tr() * 9, rad = 2.2 + tr() * 2.4;
    const cone = new THREE.ConeGeometry(rad, h, 8); cone.translate(x, h * 0.5 + 2, z); bag.add(M.tree, cone);
    const tk = new THREE.CylinderGeometry(0.25, 0.35, 2.4, 6); tk.translate(x, 1.2, z); bag.add(M.bark, tk);
  }

  bag.build(grp, false, true);
  return { grp, colliders };
}

// ============================================================ contact shadow blobs (instanced, one draw call)
class Blobs {
  constructor(max) {
    this.max = max; this.n = 0;
    const g = new THREE.PlaneGeometry(1, 1); g.rotateX(-Math.PI / 2);
    this.op = new THREE.InstancedBufferAttribute(new Float32Array(max), 1);
    this.op.setUsage(THREE.DynamicDrawUsage);
    g.setAttribute('aOp', this.op);
    const mat = new THREE.ShaderMaterial({
      transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -4, polygonOffsetUnits: -4,
      vertexShader: `attribute float aOp; varying float vOp; varying vec2 vUv;
        void main(){ vUv = uv; vOp = aOp; gl_Position = projectionMatrix * viewMatrix * modelMatrix * instanceMatrix * vec4(position, 1.0); }`,
      fragmentShader: `varying float vOp; varying vec2 vUv;
        void main(){ float r = length(vUv - 0.5) * 2.0; float a = pow(clamp(1.0 - r, 0.0, 1.0), 1.7) * vOp; gl_FragColor = vec4(0.0, 0.0, 0.0, a); }`,
    });
    this.mesh = new THREE.InstancedMesh(g, mat, max);
    this.mesh.frustumCulled = false; this.mesh.count = 0; this.mesh.renderOrder = 1;
    this.m4 = new THREE.Matrix4();
    scene.add(this.mesh);
  }
  begin() { this.n = 0; }
  push(x, z, sx, sz, op) {
    if (this.n >= this.max || op < 0.01) return;
    this.m4.makeScale(sx, 1, sz); this.m4.setPosition(x, 0.01, z);
    this.mesh.setMatrixAt(this.n, this.m4); this.op.array[this.n] = op; this.n++;
  }
  end() { this.mesh.count = this.n; this.mesh.instanceMatrix.needsUpdate = true; this.op.needsUpdate = true; }
}

// ============================================================ particles (dust, sparks, tire smoke) — visual only
class Particles {
  constructor(max, additive) {
    this.max = max; this.i = 0;
    this.pos = new Float32Array(max * 3); this.vel = new Float32Array(max * 3); this.col = new Float32Array(max * 3);
    this.life = new Float32Array(max).fill(1); this.ttl = new Float32Array(max).fill(1);
    this.s0 = new Float32Array(max); this.s1 = new Float32Array(max); this.a0 = new Float32Array(max);
    this.drag = new Float32Array(max); this.grav = new Float32Array(max);
    this.aSize = new Float32Array(max); this.aAlpha = new Float32Array(max);
    const g = new THREE.BufferGeometry();
    this.attrs = [
      new THREE.BufferAttribute(this.pos, 3), new THREE.BufferAttribute(this.aSize, 1),
      new THREE.BufferAttribute(this.aAlpha, 1), new THREE.BufferAttribute(this.col, 3),
    ];
    this.attrs.forEach((a) => a.setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('position', this.attrs[0]); g.setAttribute('aSize', this.attrs[1]);
    g.setAttribute('aAlpha', this.attrs[2]); g.setAttribute('aColor', this.attrs[3]);
    this.uScale = { value: 800 };
    const fs = additive
      ? `varying float vA; varying vec3 vC; void main(){ float r = length(gl_PointCoord - 0.5) * 2.0; float a = smoothstep(1.0, 0.0, r); gl_FragColor = vec4(vC * a * vA, 1.0); }`
      : `varying float vA; varying vec3 vC; void main(){ float r = length(gl_PointCoord - 0.5) * 2.0; float a = smoothstep(1.0, 0.1, r); gl_FragColor = vec4(vC, a * a * vA); }`;
    const mat = new THREE.ShaderMaterial({
      uniforms: { uScale: this.uScale }, transparent: true, depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      vertexShader: `uniform float uScale; attribute float aSize; attribute float aAlpha; attribute vec3 aColor; varying float vA; varying vec3 vC;
        void main(){ vec4 mv = modelViewMatrix * vec4(position, 1.0); gl_Position = projectionMatrix * mv;
          gl_PointSize = aAlpha > 0.0 ? max(1.0, aSize * uScale / max(0.1, -mv.z)) : 0.0; vA = aAlpha; vC = aColor; }`,
      fragmentShader: fs,
    });
    this.points = new THREE.Points(g, mat);
    this.points.frustumCulled = false; this.points.renderOrder = 5;
    scene.add(this.points);
  }
  reset() { this.life.fill(1); this.ttl.fill(1); this.aAlpha.fill(0); this.attrs[2].needsUpdate = true; }
  emit(x, y, z, vx, vy, vz, ttl, s0, s1, a0, r, g, b, drag, grav) {
    const i = this.i; this.i = (this.i + 1) % this.max;
    this.pos[i * 3] = x; this.pos[i * 3 + 1] = y; this.pos[i * 3 + 2] = z;
    this.vel[i * 3] = vx; this.vel[i * 3 + 1] = vy; this.vel[i * 3 + 2] = vz;
    this.col[i * 3] = r; this.col[i * 3 + 1] = g; this.col[i * 3 + 2] = b;
    this.life[i] = 0; this.ttl[i] = ttl; this.s0[i] = s0; this.s1[i] = s1; this.a0[i] = a0; this.drag[i] = drag; this.grav[i] = grav;
  }
  update(dt) {
    if (dt <= 0) return;
    for (let i = 0; i < this.max; i++) {
      if (this.life[i] >= this.ttl[i]) { this.aAlpha[i] = 0; continue; }
      this.life[i] += dt;
      const t = Math.min(1, this.life[i] / this.ttl[i]), k = Math.exp(-this.drag[i] * dt);
      this.vel[i * 3] *= k; this.vel[i * 3 + 1] = this.vel[i * 3 + 1] * k - this.grav[i] * dt; this.vel[i * 3 + 2] *= k;
      this.pos[i * 3] += this.vel[i * 3] * dt; this.pos[i * 3 + 1] += this.vel[i * 3 + 1] * dt; this.pos[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
      if (this.pos[i * 3 + 1] < 0.01) { this.pos[i * 3 + 1] = 0.01; this.vel[i * 3 + 1] *= -0.3; }
      this.aSize[i] = lerp(this.s0[i], this.s1[i], 1 - (1 - t) * (1 - t));
      this.aAlpha[i] = this.a0[i] * (1 - t) * Math.min(1, t * 8 + 0.2);
    }
    for (const a of this.attrs) a.needsUpdate = true;
  }
}

// ============================================================ skid marks (ring buffer of ground quads)
class Skids {
  constructor(max = 1800) {
    this.max = max; this.i = 0; this.total = 0; this.dirty = false;
    this.pos = new Float32Array(max * 18);
    const g = new THREE.BufferGeometry();
    this.attr = new THREE.BufferAttribute(this.pos, 3); this.attr.setUsage(THREE.DynamicDrawUsage);
    g.setAttribute('position', this.attr); g.setDrawRange(0, 0);
    this.mesh = new THREE.Mesh(g, new THREE.MeshBasicMaterial({ color: 0x060606, transparent: true, opacity: 0.55, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3 }));
    this.mesh.frustumCulled = false;
    scene.add(this.mesh);
  }
  reset() { this.i = 0; this.total = 0; this.mesh.geometry.setDrawRange(0, 0); }
  add(ax, az, bx, bz, w) {
    const dx = bx - ax, dz = bz - az, l = Math.hypot(dx, dz);
    if (l < 1e-4) return;
    const nx = (-dz / l) * w * 0.5, nz = (dx / l) * w * 0.5, y = 0.006, P = this.pos, o = this.i * 18;
    const v = [ax + nx, az + nz, ax - nx, az - nz, bx + nx, bz + nz, ax - nx, az - nz, bx - nx, bz - nz, bx + nx, bz + nz];
    for (let k = 0; k < 6; k++) { P[o + k * 3] = v[k * 2]; P[o + k * 3 + 1] = y; P[o + k * 3 + 2] = v[k * 2 + 1]; }
    this.i = (this.i + 1) % this.max; this.total = Math.min(this.total + 1, this.max); this.dirty = true;
  }
  flush() {
    if (!this.dirty) return;
    this.mesh.geometry.setDrawRange(0, this.total * 6); this.attr.needsUpdate = true; this.dirty = false;
  }
}

