// ============================================================ geometry helpers
const KEEP_ATTR = ['position', 'normal', 'uv', 'color'];
class GeoBag {
  constructor() { this.m = new Map(); }
  add(mat, geo, mtx) {
    let g = geo.index ? geo.toNonIndexed() : geo;
    if (g !== geo) geo.dispose();
    if (mtx) g.applyMatrix4(mtx);
    if (!g.attributes.normal) g.computeVertexNormals();
    if (!g.attributes.uv) g.setAttribute('uv', new THREE.Float32BufferAttribute(new Float32Array(g.attributes.position.count * 2), 2));
    for (const k of Object.keys(g.attributes)) if (!KEEP_ATTR.includes(k)) g.deleteAttribute(k);
    g.clearGroups();
    if (!this.m.has(mat)) this.m.set(mat, []);
    this.m.get(mat).push(g);
  }
  build(parent, cast, receive) {
    for (const [mat, arr] of this.m) {
      const merged = arr.length === 1 ? arr[0] : mergeGeometries(arr, false);
      if (arr.length > 1) for (const g of arr) g.dispose();
      if (!merged) continue;
      const mesh = new THREE.Mesh(merged, mat);
      mesh.castShadow = cast; mesh.receiveShadow = receive;
      parent.add(mesh);
    }
    this.m.clear();
  }
}

function boxGeo(x0, x1, y0, y1, z0, z1, r = 0) {
  const w = Math.abs(x1 - x0), h = Math.abs(y1 - y0), d = Math.abs(z1 - z0);
  const rr = Math.min(r, w / 2 - 1e-3, h / 2 - 1e-3, d / 2 - 1e-3);
  const g = rr > 0.002 ? new RoundedBoxGeometry(w, h, d, 2, rr) : new THREE.BoxGeometry(w, h, d);
  g.translate((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2);
  return g;
}
function slabGeo(p0, p1, th, z0, z1, r = 0) {
  const dx = p1[0] - p0[0], dy = p1[1] - p0[1];
  const len = Math.hypot(dx, dy);
  const g = boxGeo(-len / 2, len / 2, -th / 2, th / 2, z0, z1, r);
  g.rotateZ(Math.atan2(dy, dx));
  g.translate((p0[0] + p1[0]) / 2, (p0[1] + p1[1]) / 2, 0);
  return g;
}
function planeXZ(xa, xb, za, zb, uvs, y) {
  const g = new THREE.PlaneGeometry(xb - xa, zb - za, 1, 1);
  g.rotateX(-Math.PI / 2);
  g.translate((xa + xb) / 2, y, (za + zb) / 2);
  const p = g.attributes.position, uv = g.attributes.uv;
  for (let i = 0; i < p.count; i++) uv.setXY(i, p.getX(i) * uvs, p.getZ(i) * uvs);
  return g;
}
function colorize(g, hex) {
  const c = new THREE.Color(hex), n = g.attributes.position.count, a = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { a[i * 3] = c.r; a[i * 3 + 1] = c.g; a[i * 3 + 2] = c.b; }
  g.setAttribute('color', new THREE.BufferAttribute(a, 3));
  return g;
}
function prismGeo(top, bot) {
  const pos = [], n = top.length;
  const tri = (a, b, c) => pos.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z);
  for (let i = 1; i < n - 1; i++) { tri(top[0], top[i], top[i + 1]); tri(bot[0], bot[i + 1], bot[i]); }
  for (let i = 0; i < n; i++) { const j = (i + 1) % n; tri(top[i], bot[i], bot[j]); tri(top[i], bot[j], top[j]); }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(new Float32Array((pos.length / 3) * 2), 2));
  g.computeVertexNormals();
  return g;
}
function sampleX(a, b, n) { const r = []; for (let i = 0; i <= n; i++) r.push(a + (b - a) * (i / n)); return r; }
function loftGeo(xs, prof, s, sc) {
  const K = prof(xs[0]).length, nx = xs.length;
  const pos = new Float32Array(nx * K * 3), uv = new Float32Array(nx * K * 2), tx = new Float32Array(nx * K);
  for (let i = 0; i < nx; i++) {
    const x = xs[i], pr = prof(x);
    for (let k = 0; k < K; k++) {
      const vi = i * K + k;
      pos[vi * 3] = x * sc.sx; pos[vi * 3 + 1] = pr[k][0] * sc.sy; pos[vi * 3 + 2] = pr[k][1] * sc.sz * s;
      uv[vi * 2] = i / (nx - 1); uv[vi * 2 + 1] = k / (K - 1); tx[vi] = x;
    }
  }
  const idx = [];
  for (let i = 0; i < nx - 1; i++) for (let k = 0; k < K - 1; k++) {
    const a = i * K + k, b = (i + 1) * K + k, c = b + 1, d = a + 1;
    idx.push(a, b, d, b, c, d);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  return { geo: g, base: pos.slice(), tx, K, nx, s };
