    bond: { stages: ['fixed'], F: [2e3, 4, 6e3] } });
  let k = 0;
  for (const [id, s, , , front] of doors) {
    const zg = 0.815 * s;
    const pts = front ? [[-0.02, 0.905], [0.84, 0.905], [0.32, 1.34], [-0.02, 1.34]] : [[-0.90, 0.905], [-0.11, 0.905], [-0.11, 1.34], [-0.78, 1.34]];
    P.push({ id: id + 'Glass', label: `${front ? 'Front' : 'Rear'} ${s > 0 ? 'right' : 'left'} side glass`, mf: 0.003, parent: id, host: id, mount: { type: 'fixed' },
      pane: { pts: pts.map((q) => [q[0], q[1], zg]), th: 0.01, n: 8, seed: 303 + 17 * k++ },
      bond: { stages: ['fixed'], F: [1.2e3, 2.5, 4e3], strain: front ? 0.75 : 0 } });
  }
  return P;
}

// ============================================================ simulation run
class Sim {
  constructor(cfg) {
    this.cfg = { ...cfg };
    const c = this.cfg, L = c.trackLength, wallFront = L / 2 - 7;
    this.layout = {
      x0: -L / 2, x1: L / 2, wallFront, carRear: -L / 2 + 1.5, carLen: c.carLength, carWid: c.carWidth, carZ: 0.35,
      startLine: -L / 2 + 1.5 + c.carLength + 0.6, runoffEnd: wallFront + 28,
      zB: Math.max(9.5, (c.wallCols * c.brickW) / 2 + 2.5),
    };
    this.world = new RAPIER.World({ x: 0, y: -c.gravity, z: 0 });
    this.world.timestep = DT;
    const ip = this.world.integrationParameters;
    ip.numSolverIterations = 8;
    ip.maxCcdSubsteps = 2;
    this.eq = new RAPIER.EventQueue(true);
    this.owners = new Map();
    this.group = new THREE.Group();
    scene.add(this.group);
    this.tracked = []; this.parts = []; this.partById = {}; this.bricks = []; this.shards = [];
    this.stepIndex = 0; this.time = 0; this.phase = 'idle';
    this.releaseT = null; this.impactT = null; this.cmdV = 0; this.driveStep = 0;
    this.crushD = 0; this.dVis = 0; this.dApplied = -1;
    this.shake = 0; this.aHist = []; this.settleCount = 0; this.dustBudget = 0; this.sparkBudget = 0;
    this.stats = { impactSpeed: null, peakG: 0, detached: 0, panes: 0, shards: 0, bricksMoved: 0 };
    this.log = []; this.fxq = []; this.physMs = 0;
    this.vr = mulberry32(4242);
    this.onForceBound = (ev) => this.onForce(ev);

    this.buildStatic();
    this.buildWall();
    this.buildCar();
    const D = Math.max(2, wallFront - (this.layout.carRear + c.carLength));
    this.accel = (c.speed * c.speed) / (2 * 0.8 * D);
    const hMax = Math.max(2.5, c.wallRows * c.brickH + 0.6, c.carHeight + 0.6);
    fitShadow(this.layout.carRear - 3, wallFront + 24, -this.layout.zB, this.layout.zB, 0, hMax);
    this.wallCenter = new THREE.Vector3(wallFront + (c.wallDepth * c.brickD) / 2, (c.wallRows * c.brickH) / 2, 0);
    this.addLog('Staged on the grid');
  }

  addLog(text) { this.log.push({ t: this.time, text }); if (this.log.length > 7) this.log.shift(); this.logDirty = true; }

  buildStatic() {
    const env = buildEnvironment(this.layout);
    this.envGroup = env.grp;
    scene.add(env.grp);
    const gb = this.world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
    const gc = this.world.createCollider(RAPIER.ColliderDesc.cuboid(400, 0.5, 400).setTranslation(0, -0.5, 0).setFriction(this.cfg.groundFriction).setRestitution(0.05), gb);
    this.owners.set(gc.handle, { kind: 'ground' });
    for (const b of env.colliders) {
      const cc = this.world.createCollider(RAPIER.ColliderDesc.cuboid(b.h[0], b.h[1], b.h[2]).setTranslation(b.c[0], b.c[1], b.c[2]).setFriction(0.6).setRestitution(0.2), gb);
      this.owners.set(cc.handle, { kind: 'static' });
    }
  }

  track(body, obj, he, blob, im = null, idx = 0) {
    const t = body.translation(), q = body.rotation();
    const r = { body, obj, im, idx, he, blob, alive: true,
      px: t.x, py: t.y, pz: t.z, qx: q.x, qy: q.y, qz: q.z, qw: q.w,
      cx: t.x, cy: t.y, cz: t.z, cqx: q.x, cqy: q.y, cqz: q.z, cqw: q.w };
    this.tracked.push(r);
    if (obj) { obj.position.set(t.x, t.y, t.z); obj.quaternion.set(q.x, q.y, q.z, q.w); }
    return r;
  }

  buildWall() {
    const c = this.cfg, L = this.layout;
    const w = c.brickW, h = c.brickH, d = c.brickD;
    const gap = Math.min(0.004, w * 0.02);
    const mort = Math.min(0.012, Math.min(w, h, d) * 0.07);
    const Ww = c.wallCols * w;
    const list = [];
    for (let k = 0; k < c.wallDepth; k++) for (let r = 0; r < c.wallRows; r++) {
      const off = (r + k) % 2 === 1;
      const x = L.wallFront + d / 2 + k * (d + 0.004), y = h / 2 + r * h;
      if (!off) for (let i = 0; i < c.wallCols; i++) list.push({ x, y, z: -Ww / 2 + w / 2 + i * w, half: false });
      else {
        list.push({ x, y, z: -Ww / 2 + w / 4, half: true });
        for (let i = 0; i < c.wallCols - 1; i++) list.push({ x, y, z: -Ww / 2 + w + i * w, half: false });
        list.push({ x, y, z: Ww / 2 - w / 4, half: true });
      }
    }
    const nFull = list.filter((b) => !b.half).length, nHalf = list.length - nFull;
    const rad = Math.max(0, Math.min(0.012, (Math.min(w / 2, h, d) - mort) * 0.15));
    const meshF = new THREE.InstancedMesh(new RoundedBoxGeometry(d - mort, h - mort, w - mort, 2, rad), M.brick, Math.max(1, nFull));
    const meshH = new THREE.InstancedMesh(new RoundedBoxGeometry(d - mort, h - mort, w / 2 - mort, 2, rad), M.brick, Math.max(1, nHalf));
    meshF.count = nFull; meshH.count = nHalf;
    for (const m of [meshF, meshH]) { m.castShadow = true; m.receiveShadow = true; m.frustumCulled = false; this.group.add(m); }
    this.brickMeshes = [meshF, meshH];
    const pal = [0x8e3b2a, 0x9c4630, 0xa8523a, 0x7d3326, 0xb25c40, 0x6e2e22, 0x94412d];
    const pr = mulberry32(7), col = new THREE.Color();
    const CFE = RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS;
    let iF = 0, iH = 0;
    for (const b of list) {
      const bw = b.half ? w / 2 : w, m = b.half ? c.brickMass / 2 : c.brickMass;
      const body = this.world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(b.x, b.y, b.z).setCcdEnabled(true));
      const cd = RAPIER.ColliderDesc.cuboid(d / 2 - 0.001, h / 2, bw / 2 - gap / 2).setMass(m)
        .setFriction(c.brickFriction).setRestitution(c.brickRestitution)
        .setActiveEvents(CFE).setContactForceEventThreshold(Math.max(250, m * 9.81 * 30));
      const cc = this.world.createCollider(cd, body);
      const mesh = b.half ? meshH : meshF, idx = b.half ? iH++ : iF++;
      const rec = { body, x0: b.x, y0: b.y, z0: b.z, m };
      this.owners.set(cc.handle, { kind: 'brick', ref: rec });
      col.setHex(pal[(pr() * pal.length) | 0]).multiplyScalar(0.86 + pr() * 0.28);
      if (pr() < 0.06) col.multiplyScalar(0.55);
      mesh.setColorAt(idx, col);
      rec.track = this.track(body, null, [d / 2, h / 2, bw / 2], 0.42, mesh, idx);
      this.bricks.push(rec);
    }
    for (const m of [meshF, meshH]) if (m.instanceColor) m.instanceColor.needsUpdate = true;
    this.dustThresh = Math.max(400, c.brickMass * 9.81 * 40);
  }

  S3(v) { return [v[0] * this.sc.sx, v[1] * this.sc.sy, v[2] * this.sc.sz]; }

  buildCar() {
    const c = this.cfg;
    const sx = c.carLength / 4.2, sy = c.carHeight / 1.45, sz = c.carWidth / 1.8;
    this.sc = { sx, sy, sz, st: (sx + sy) / 2, sm: Math.min(sx, sy, sz) };
    this.carBase = [this.layout.carRear + c.carLength / 2, 0.004, this.layout.carZ];
    this.crushMax = TPL.CRUSH * sx;
    this.crushForce = 20 * c.carMass;
    this.strScale = Math.sqrt(c.carMass / 1250);
    this.brakeTorque = 1800 * (c.carMass / 1250);
    for (const sp of carSpec()) this.makePart(sp);
    this.cabin = this.partById.cabin;
    this.bondParts = this.parts.filter((p) => p.spec.bond);
    this.detachables = this.bondParts.filter((p) => !p.pane).length;
    this.paneCount = this.parts.filter((p) => p.pane).length;
    this.wheels = this.parts.filter((p) => p.spec.wheel);
    const bf = this.partById.bumperF;
    bf.frontOff = 2.10 * sx - bf.origin[0];
    this.rel0x = this.partById.nose.origin[0] - this.partById.front.origin[0];
  }

  makePart(sp) {
    const { sx, sy, sz, st } = this.sc;
    const part = { id: sp.id, spec: sp, mass: sp.mf * this.cfg.carMass, alive: true, fc: 0, dmg: 0, lastLoad: 0, stageIdx: 0, stage: 'perm', v0x: 0, v0y: 0, v0z: 0 };
    const cols = [];
    const bmin = [Infinity, Infinity, Infinity], bmax = [-Infinity, -Infinity, -Infinity];
    const grow = (c, h) => { for (let i = 0; i < 3; i++) { bmin[i] = Math.min(bmin[i], c[i] - h[i]); bmax[i] = Math.max(bmax[i], c[i] + h[i]); } };
    if (sp.pane) {
      const pts = sp.pane.pts.map((p) => new THREE.Vector3(...this.S3(p)));
      const e1 = pts[1].clone().sub(pts[0]), e2 = pts[2].clone().sub(pts[0]);
      const u = e1.clone().normalize(), n = e1.clone().cross(e2).normalize(), v = n.clone().cross(u);
      const O = new THREE.Vector3();
      pts.forEach((p) => O.add(p)); O.multiplyScalar(1 / pts.length);
      let poly = pts.map((p) => { const d = p.clone().sub(O); return [d.dot(u), d.dot(v)]; });
      const c2 = polyCentroid(poly);
      O.addScaledVector(u, c2[0]).addScaledVector(v, c2[1]);
      poly = poly.map((q) => [q[0] - c2[0], q[1] - c2[1]]);
      const th = sp.pane.th * st;
      part.pane = { u, v, n, poly, th, cells: voronoi2D(poly, sp.pane.n, sp.pane.seed), area: Math.abs(polyArea(poly)) };
      part.origin = [O.x, O.y, O.z];
      const hull = [];
      for (const q of poly) for (const sg of [-0.5, 0.5]) {
        const P = u.clone().multiplyScalar(q[0]).addScaledVector(v, q[1]).addScaledVector(n, th * sg);
        hull.push(P.x, P.y, P.z);
        grow([O.x + P.x, O.y + P.y, O.z + P.z], [0, 0, 0]);
      }
      const hd = RAPIER.ColliderDesc.convexHull(new Float32Array(hull)) || RAPIER.ColliderDesc.cuboid(0.2 * sx, 0.2 * sy, th / 2);
      cols.push({ desc: hd, center: [0, 0, 0], vol: part.pane.area * th });
    } else {
      const raw = [];
      for (const cd of sp.cols) {
        if (cd.t === 'box') {
          const [x0, x1, y0, y1, z0, z1] = cd.b;
          const c = [((x0 + x1) / 2) * sx, ((y0 + y1) / 2) * sy, ((z0 + z1) / 2) * sz];
          const h = [(Math.abs(x1 - x0) / 2) * sx, (Math.abs(y1 - y0) / 2) * sy, (Math.abs(z1 - z0) / 2) * sz];
          raw.push({ kind: 'box', c, h, vol: 8 * h[0] * h[1] * h[2] });
          grow(c, h);
        } else if (cd.t === 'slab') {
          const p0 = [cd.p0[0] * sx, cd.p0[1] * sy], p1 = [cd.p1[0] * sx, cd.p1[1] * sy];
          const len = Math.hypot(p1[0] - p0[0], p1[1] - p0[1]), ang = Math.atan2(p1[1] - p0[1], p1[0] - p0[0]);
          const th = cd.th * st, hz = (Math.abs(cd.z1 - cd.z0) / 2) * sz;
          const c = [(p0[0] + p1[0]) / 2, (p0[1] + p1[1]) / 2, ((cd.z0 + cd.z1) / 2) * sz];
          const ca = Math.abs(Math.cos(ang)), sa = Math.abs(Math.sin(ang));
          raw.push({ kind: 'slab', c, h: [len / 2, th / 2, hz], ang, vol: len * th * 2 * hz });
          grow(c, [(ca * len) / 2 + (sa * th) / 2, (sa * len) / 2 + (ca * th) / 2, hz]);
        } else {
          const c = this.S3(cd.c), R = TPL.R * sy, hw = (TPL.WW * sz) / 2;
          raw.push({ kind: 'wheel', c, R, hw, vol: Math.PI * R * R * 2 * hw });
          grow(c, [R, R, hw]);
          part.wheelR = R; part.wheelHW = hw;
        }
      }
      part.origin = [(bmin[0] + bmax[0]) / 2, (bmin[1] + bmax[1]) / 2, (bmin[2] + bmax[2]) / 2];
      const o = part.origin;
      for (const r of raw) {
        const lc = [r.c[0] - o[0], r.c[1] - o[1], r.c[2] - o[2]];
        let desc;
        if (r.kind === 'box') desc = RAPIER.ColliderDesc.cuboid(r.h[0], r.h[1], r.h[2]);
        else if (r.kind === 'slab') desc = RAPIER.ColliderDesc.cuboid(r.h[0], r.h[1], r.h[2]).setRotation({ x: 0, y: 0, z: Math.sin(r.ang / 2), w: Math.cos(r.ang / 2) });
        else {
          const br = Math.min(0.03, r.hw * 0.4);
          desc = RAPIER.ColliderDesc.roundCylinder(r.hw - br, r.R - br, br).setRotation({ x: Math.SQRT1_2, y: 0, z: 0, w: Math.SQRT1_2 });
        }
        desc.setTranslation(lc[0], lc[1], lc[2]);
        cols.push({ desc, center: lc, vol: r.vol });
      }
    }
    part.he = [(bmax[0] - bmin[0]) / 2, (bmax[1] - bmin[1]) / 2, (bmax[2] - bmin[2]) / 2];
    const o = part.origin;
    const vt = cols.reduce((a, c) => a + c.vol, 0);
    const lcom = [0, 0, 0];
    const CFE = RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS;
    const fr = sp.wheel ? 1.0 : sp.pane ? 0.4 : 0.5, re = sp.wheel ? 0.1 : sp.pane ? 0.1 : 0.12;
    const bd = RAPIER.RigidBodyDesc.dynamic()
      .setTranslation(this.carBase[0] + o[0], this.carBase[1] + o[1], this.carBase[2] + o[2])
      .setCcdEnabled(true).setAngularDamping(sp.wheel ? 0.02 : 0.06);
    part.body = this.world.createRigidBody(bd);
    part.colliders = [];
    for (const c of cols) {
      const m = part.mass * (c.vol / vt);
      for (let i = 0; i < 3; i++) lcom[i] += c.center[i] * m;
      c.desc.setMass(m).setFriction(fr).setRestitution(re).setActiveEvents(CFE).setContactForceEventThreshold(300);
      const cc = this.world.createCollider(c.desc, part.body);
      this.owners.set(cc.handle, { kind: 'part', ref: part });
      part.colliders.push(cc);
    }
    part.localCom = [lcom[0] / part.mass, lcom[1] / part.mass, lcom[2] / part.mass];

    if (sp.mount) {
      const par = this.partById[sp.parent];
      part.parent = par;
      const at = sp.mount.at ? this.S3(sp.mount.at) : o.slice();
      const a1 = { x: at[0] - par.origin[0], y: at[1] - par.origin[1], z: at[2] - par.origin[2] };
      const a2 = { x: at[0] - o[0], y: at[1] - o[1], z: at[2] - o[2] };
      let jd;
      if (sp.mount.type === 'fixed') jd = RAPIER.JointData.fixed(a1, QI, a2, QI);
      else if (sp.mount.type === 'revolute') { const ax = sp.mount.axis; jd = RAPIER.JointData.revolute(a1, a2, { x: ax[0], y: ax[1], z: ax[2] }); }
      else { jd = RAPIER.JointData.prismatic(a1, a2, { x: 1, y: 0, z: 0 }); jd.limitsEnabled = true; jd.limits = [-this.crushMax, 0.002]; }
      part.joint = this.world.createImpulseJoint(jd, par.body, part.body, true);
      part.joint.setContactsEnabled(!!sp.contacts);
      part.stage = sp.bond ? sp.bond.stages[0] : 'perm';
    }

    part.obj = new THREE.Group();
    this.group.add(part.obj);
    const bag = new GeoBag();
    this.buildPartVisual(part, bag, new THREE.Matrix4().makeTranslation(-o[0], -o[1], -o[2]));
    bag.build(part.obj, true, true);
    const blob = sp.pane ? 0 : sp.id === 'cabin' ? 0.62 : sp.id === 'front' ? 0.5 : 0.4;
    part.rec = this.track(part.body, part.obj, part.he, blob);
    this.parts.push(part);
    this.partById[sp.id] = part;
    return part;
  }

  buildPartVisual(p, bag, toLocal) {
    const { sx, sy, sz, st, sm } = this.sc;
    const sp = p.spec;
    const box = (mat, x0, x1, y0, y1, z0, z1, r = 0) => bag.add(mat, boxGeo(x0 * sx, x1 * sx, y0 * sy, y1 * sy, z0 * sz, z1 * sz, r * sm), toLocal);
    const boxB = (mat, x0, x1, y0, y1, z0, z1, r = 0) => { box(mat, x0, x1, y0, y1, z0, z1, r); box(mat, x0, x1, y0, y1, -z1, -z0, r); };
    const slab = (mat, p0, p1, th, z0, z1, r = 0) => bag.add(mat, slabGeo([p0[0] * sx, p0[1] * sy], [p1[0] * sx, p1[1] * sy], th * st, z0 * sz, z1 * sz, r * sm), toLocal);
    const slabB = (mat, p0, p1, th, z0, z1, r = 0) => { slab(mat, p0, p1, th, z0, z1, r); slab(mat, p0, p1, th, -z1, -z0, r); };
    const geo = (mat, g) => bag.add(mat, g, toLocal);
    const zs = (s, a, b) => (s > 0 ? [a, b] : [-b, -a]);
    const V3 = (x, y, z) => new THREE.Vector3(x * sx, y * sy, z * sz);

    if (sp.pane) {
      const pn = p.pane, top = [], bot = [];
      for (const q of pn.poly) {
        const P = pn.u.clone().multiplyScalar(q[0]).addScaledVector(pn.v, q[1]);
        top.push(P.clone().addScaledVector(pn.n, pn.th / 2));
        bot.push(P.clone().addScaledVector(pn.n, -pn.th / 2));
      }
      bag.add(M.glass, prismGeo(top, bot), null);
      return;
    }
    if (sp.wheel) { this.wheelVisual(p, bag); return; }
    if (sp.door) {
      const s = sp.side, x0 = sp.cols[0].b[0], x1 = sp.cols[0].b[1];
      box(M.paint, x0, x1, 0.33, 0.88, ...zs(s, 0.795, 0.875), 0.025);
      box(M.interior, x0 + 0.02, x1 - 0.02, 0.36, 0.86, ...zs(s, 0.785, 0.797));
      box(M.trim, x0 + 0.01, x1 - 0.01, 0.875, 0.895, ...zs(s, 0.80, 0.84), 0.005);
      box(M.chrome, x0 + 0.08, x0 + 0.22, 0.74, 0.765, ...zs(s, 0.872, 0.89), 0.006);
      if (sp.front) {
        box(M.trim, -0.02, 0.34, 1.34, 1.37, ...zs(s, 0.80, 0.83));
        box(M.trim, -0.04, -0.01, 0.88, 1.37, ...zs(s, 0.80, 0.83));
        slab(M.trim, [0.86, 0.895], [0.32, 1.36], 0.03, ...zs(s, 0.80, 0.83));
        box(M.paint, 0.64, 0.80, 0.92, 1.02, ...zs(s, 0.86, 1.00), 0.03);
        box(M.trim, 0.70, 0.76, 0.885, 0.93, ...zs(s, 0.84, 0.90));
        box(M.chrome, 0.636, 0.645, 0.93, 1.01, ...zs(s, 0.87, 0.99));
      } else {
        box(M.trim, -0.78, -0.09, 1.34, 1.37, ...zs(s, 0.80, 0.83));
        box(M.trim, -0.11, -0.08, 0.88, 1.37, ...zs(s, 0.80, 0.83));
        slab(M.trim, [-0.92, 0.895], [-0.78, 1.36], 0.03, ...zs(s, 0.80, 0.83));
      }
      return;
    }
    switch (p.id) {
      case 'cabin': {
        for (const s of [1, -1]) {
          geo(M.paint, loftGeo(sampleX(-2.0, -0.95, 30), (x) => {
            const yb = archBottom(x, TPL.AXR, 0.30);
            return [[yb, 0.872], [(yb + 0.86) / 2, 0.879], [0.84, 0.877], [0.872, 0.864], [0.893, 0.838], [0.903, 0.80], [0.905, 0.62]];
          }, s, this.sc).geo);
          geo(M.paint, loftGeo(sampleX(-0.95, 0.915, 12), () => [[0.19, 0.86], [0.205, 0.876], [0.31, 0.878], [0.325, 0.862], [0.33, 0.80]], s, this.sc).geo);
          geo(M.paint, prismGeo([V3(-1.24, 0.905, 0.80 * s), V3(-0.93, 0.905, 0.80 * s), V3(-0.80, 1.38, 0.80 * s)], [V3(-1.24, 0.905, 0.76 * s), V3(-0.93, 0.905, 0.76 * s), V3(-0.80, 1.38, 0.76 * s)]));
        }
        box(M.paint, -2.035, -1.975, 0.30, 0.905, -0.86, 0.86, 0.035);
        boxB(M.tail, -2.047, -2.025, 0.72, 0.84, 0.50, 0.83, 0.012);
