const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.enabled = false;
controls.autoRotate = true;
controls.autoRotateSpeed = 1.0;
controls.minDistance = 3;
controls.maxDistance = 90;
controls.maxPolarAngle = Math.PI * 0.485;
let userOrbited = false;
controls.addEventListener('start', () => { userOrbited = true; controls.autoRotate = false; });

let sim = null, paused = false, timeScale = 1, view = 'impact', acc = 0, camInit = true, orbitFocus = 0;
const camPos = new THREE.Vector3(), camLook = new THREE.Vector3(), followPos = new THREE.Vector3(), followLook = new THREE.Vector3();

function focusX() {
  const c = sim.cabin.obj.position, wx = sim.layout.wallFront;
  if (sim.phase === 'idle' || sim.phase === 'drive') {
    const dist = Math.max(0, wx - (c.x + sim.cfg.carLength / 2));
    return lerp(c.x, wx, 0.18 + 0.32 * (1 - smooth(3, 22, dist)));
  }
  return clamp(0.5 * c.x + 0.5 * wx, wx - 2, wx + 7);
}

function resetOrbit() {
  const tx = focusX();
  camera.up.set(0, 1, 0);
  controls.target.set(tx, 0.8, 0);
  camera.position.set(tx - 9, 4.8, 12.5);
  orbitFocus = tx;
  controls.autoRotate = !userOrbited;
  controls.update();
}

function updateCamera(rdt, sdt) {
  const s = sim, c = s.cabin.obj.position;
  let fov = 38;
  if (view === 'impact') {
    camera.up.set(0, 1, 0);
    const tx = focusX();
    camPos.set(tx - 7.6, 2.25, 11.2);
    camLook.set(tx, 0.95, 0.2);
  } else if (view === 'follow') {
    camera.up.set(0, 1, 0);
    fov = 50;
    const wantP = _v1.set(c.x - 8.2, Math.max(1.2, c.y + 2.7), c.z + 3.6);
    const wantL = _v2.set(c.x + 3.6, Math.max(0.3, c.y + 0.35), c.z - 0.5);
    if (camInit) { followPos.copy(wantP); followLook.copy(wantL); }
    else {
      const k = 1 - Math.exp(-sdt * 10);
      followPos.lerp(wantP, k); followLook.lerp(wantL, k);
    }
    camPos.copy(followPos); camLook.copy(followLook);
  } else if (view === 'top') {
    const L = s.layout, xa = L.carRear - 3, xb = L.runoffEnd + 2, za = -L.zB - 1, zb = L.zB + 1;
    const t = Math.tan(THREE.MathUtils.degToRad(fov / 2));
    const H = Math.max((xb - xa) / (2 * t * camera.aspect), (zb - za) / (2 * t)) * 1.04;
    camera.up.set(0, 0, -1);
    camPos.set((xa + xb) / 2, H, (za + zb) / 2);
    camLook.set((xa + xb) / 2, 0, (za + zb) / 2);
  }
  if (camera.fov !== fov) { camera.fov = fov; camera.updateProjectionMatrix(); }
  if (view === 'orbit') {
    const tx = focusX(), dx = tx - orbitFocus;
    orbitFocus = tx;
    camera.position.x += dx; controls.target.x += dx;
    controls.update(rdt);
  } else {
    if (view !== 'top' && s.shake > 0.01) {
      const a = s.shake * s.shake * 0.16, t = s.time;
      const ox = Math.sin(t * 67.3) * a, oy = Math.sin(t * 83.1 + 1.3) * a * 0.6, oz = Math.sin(t * 59.7 + 2.1) * a;
      camPos.x += ox; camPos.y += oy; camPos.z += oz;
