function updatePlayUI() {
  $('icPlay').innerHTML = paused ? PLAY_ICON : PAUSE_ICON;
  $('bPlayTxt').textContent = paused ? 'Play' : 'Pause';
}
function togglePause() { paused = !paused; updatePlayUI(); hud(); }

function setView(v) {
  view = v;
  document.querySelectorAll('#gView button').forEach((b) => b.classList.toggle('on', b.dataset.v === v));
  controls.enabled = v === 'orbit';
  camInit = true;
  if (v === 'orbit') resetOrbit();
}

function buildSettings() {
  let html = '', g = null;
  for (const s of SCHEMA) {
    if (s.g !== g) { if (g) html += '</div>'; html += `<div class="sg"><h4>${s.g}</h4>`; g = s.g; }
    html += `<label class="f"><span>${s.l}</span><input id="in_${s.k}" type="number" inputmode="decimal" min="${s.min}" max="${s.max}" step="${s.step}" value="${DEFAULTS[s.k]}"><em>${s.u}</em></label>`;
  }
  html += '</div>';
  const body = $('setBody');
  body.innerHTML = html;
  body.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); startRun(readSettings()); } });
}
function readSettings() {
  const cfg = {};
  for (const s of SCHEMA) {
    const el = $('in_' + s.k);
    let v = parseFloat(el.value);
    if (!Number.isFinite(v)) v = DEFAULTS[s.k];
    v = clamp(v, s.min, s.max);
    if (s.int) v = Math.round(v);
    cfg[s.k] = v;
    el.value = String(v);
  }
  return cfg;
