  if (sim) sim.dispose();
  dust.reset(); sparks.reset(); skids.reset();
  M.startLight.emissiveIntensity = 2.4;
  sim = new Sim(cfg);
  acc = 0; paused = false; camInit = true;
  updatePlayUI();
  if (view === 'orbit') resetOrbit();
  sim.sync(1);
  hud();
