const hudEl = {};
for (const k of ['statusTxt', 'hTime', 'hSpeed', 'hImpact', 'hDecel', 'hCrush', 'hParts', 'hShards', 'hBricks', 'hBodies', 'hPhys', 'log', 'status']) hudEl[k] = $(k);
