  const s = sim, st = s.stats;
  let state, label;
  if (paused) { state = 'paused'; label = 'Paused'; }
  else if (s.phase === 'idle') { state = 'idle'; label = 'Staged'; }
  else if (s.phase === 'drive') { state = 'approach'; label = 'Approach'; }
  else if (s.phase === 'crash') {
    if (s.impactT === null || s.time - s.impactT < 0.35) { state = 'impact'; label = 'Impact'; }
    else { state = 'breakup'; label = 'Breakup'; }
  } else { state = 'settled'; label = 'Settled · holding'; }
  hudEl.status.dataset.s = state;
  hudEl.statusTxt.textContent = label;
  const v = s.cabin.body.linvel(), spd = Math.hypot(v.x, v.y, v.z);
  hudEl.hTime.textContent = `${s.time.toFixed(2)} s`;
  hudEl.hSpeed.textContent = `${spd.toFixed(1)} m/s · ${(spd * 3.6).toFixed(0)} km/h`;
  hudEl.hImpact.textContent = st.impactSpeed == null ? '–' : `${st.impactSpeed.toFixed(1)} m/s · ${(st.impactSpeed * 3.6).toFixed(0)} km/h`;
  hudEl.hDecel.textContent = st.peakG > 0 ? `${st.peakG.toFixed(1)} g` : '–';
  hudEl.hCrush.textContent = `${(s.dVis * 100).toFixed(0)} cm`;
  hudEl.hParts.textContent = `${st.detached} / ${s.detachables}`;
  hudEl.hShards.textContent = `${st.shards} · ${st.panes}/${s.paneCount} panes`;
  hudEl.hBricks.textContent = `${st.bricksMoved} / ${s.bricks.length}`;
  hudEl.hBodies.textContent = String(s.bodyCount);
  hudEl.hPhys.textContent = `${s.physMs.toFixed(2)} ms`;
  if (s.logDirty) {
    hudEl.log.innerHTML = s.log.slice(-6).map((e) => `<div><b>${e.t.toFixed(2)}s</b>${e.text}</div>`).join('');
    s.logDirty = false;
  }
}

$('bPlay').addEventListener('click', togglePause);
$('bReplay').addEventListener('click', () => startRun(readSettings()));
$('bApply').addEventListener('click', () => startRun(readSettings()));
$('bDefaults').addEventListener('click', () => { fillSettings(DEFAULTS); startRun(readSettings()); });
$('bSettings').addEventListener('click', () => { const o = $('settings').classList.toggle('open'); $('bSettings').classList.toggle('on', o); });
document.querySelectorAll('#gSpeed button').forEach((b) => b.addEventListener('click', () => {
  timeScale = parseFloat(b.dataset.s);
  document.querySelectorAll('#gSpeed button').forEach((x) => x.classList.toggle('on', x === b));
}));
document.querySelectorAll('#gView button').forEach((b) => b.addEventListener('click', () => setView(b.dataset.v)));
document.querySelectorAll('#bar button, .acts button').forEach((b) => b.addEventListener('mousedown', (e) => e.preventDefault()));

window.addEventListener('keydown', (e) => {
  if (!sim || e.metaKey || e.ctrlKey || e.altKey) return;
  const tag = document.activeElement ? document.activeElement.tagName : '';
  const typing = tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
  if (e.code === 'Space') { if (typing) return; e.preventDefault(); togglePause(); return; }
  if (typing) return;
  if (e.key === 'r' || e.key === 'R') startRun(readSettings());
  else if (e.key >= '1' && e.key <= '4') setView(['impact', 'follow', 'top', 'orbit'][+e.key - 1]);
});

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ============================================================ main loop
let last = performance.now(), hudT = 0;
function frame(now) {
  requestAnimationFrame(frame);
  const rdt = Math.min(0.1, Math.max(0, (now - last) / 1000));
  last = now;
  let n = 0;
  if (!paused && sim.phase !== 'settled') {
    acc += rdt * timeScale;
    while (acc >= DT && n < MAX_STEPS && sim.phase !== 'settled') { sim.step(); acc -= DT; n++; }
    if (acc >= DT) acc = 0;
    if (sim.phase === 'settled') acc = 0;
  }
  const fxDt = paused ? 0 : sim.phase === 'settled' && n === 0 ? rdt * timeScale : n * DT;
  dust.update(fxDt);
  sparks.update(fxDt);
  sim.sync(sim.phase === 'settled' ? 1 : clamp(acc / DT, 0, 1));
  updateCamera(rdt, n * DT);
  hudT += rdt;
  if (hudT > 0.12) { hudT = 0; hud(); }
  renderer.render(scene, camera);
}

async function init() {
  try {
    await RAPIER.init();
  } catch (err) {
    $('loading').textContent = 'Physics engine failed to load';
    throw err;
  }
  $('loading').remove();
  buildSettings();
  startRun({ ...DEFAULTS });
  last = performance.now();
  requestAnimationFrame(frame);
}
init();
