// ============================================================ procedural textures (seeded, visual only)
function makeCanvas(w, h) { const c = document.createElement('canvas'); c.width = w; c.height = h; return [c, c.getContext('2d')]; }
function texFrom(c, srgb) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.needsUpdate = true;
  return t;
}
function blotches(g, S, n, rnd, colorFn) {
  for (let i = 0; i < n; i++) {
    const x = rnd() * S, y = rnd() * S, r = S * (0.04 + rnd() * 0.18);
    const col = colorFn(rnd);
    for (const ox of [-S, 0, S]) for (const oy of [-S, 0, S]) {
      const gd = g.createRadialGradient(x + ox, y + oy, 0, x + ox, y + oy, r);
      gd.addColorStop(0, col); gd.addColorStop(1, 'rgba(0,0,0,0)');
      g.fillStyle = gd; g.fillRect(x + ox - r, y + oy - r, r * 2, r * 2);
    }
  }
}
function makeTextures() {
  const rnd = mulberry32(1337);
  const T = {};
  {
    const S = 512; const [c, g] = makeCanvas(S, S); const [cr, gr] = makeCanvas(S, S);
    g.fillStyle = '#3e4145'; g.fillRect(0, 0, S, S);
    gr.fillStyle = 'rgb(214,214,214)'; gr.fillRect(0, 0, S, S);
    blotches(g, S, 70, rnd, (r) => (r() < 0.55 ? `rgba(18,20,22,${0.08 + r() * 0.08})` : `rgba(125,125,120,${0.04 + r() * 0.05})`));
    blotches(gr, S, 40, rnd, (r) => `rgba(${r() < 0.5 ? 150 : 255},${r() < 0.5 ? 150 : 255},${r() < 0.5 ? 150 : 255},0.12)`);
    for (let i = 0; i < 32000; i++) {
      const x = rnd() * S, y = rnd() * S, s = rnd() < 0.86 ? 1 : 2, l = rnd();
      const v = l < 0.5 ? 18 + l * 70 : 80 + l * 90;
      g.fillStyle = `rgba(${v | 0},${v | 0},${(v * 1.03) | 0},${0.3 + rnd() * 0.45})`; g.fillRect(x, y, s, s);
      const rv = (140 + rnd() * 115) | 0; gr.fillStyle = `rgb(${rv},${rv},${rv})`; gr.fillRect(x, y, s, s);
    }
    T.asphalt = texFrom(c, true); T.asphaltRough = texFrom(cr, false);
  }
  {
    const S = 256; const [c, g] = makeCanvas(S, S);
    g.fillStyle = '#4b6a2c'; g.fillRect(0, 0, S, S);
    blotches(g, S, 50, rnd, (r) => (r() < 0.5 ? 'rgba(40,62,20,0.35)' : 'rgba(112,140,60,0.22)'));
    g.lineWidth = 1;
    for (let i = 0; i < 9000; i++) {
      const x = rnd() * S, y = rnd() * S, a = -Math.PI / 2 + (rnd() - 0.5) * 0.9, l = 2 + rnd() * 4;
      const gg = (70 + rnd() * 80) | 0;
      g.strokeStyle = `rgba(${(gg * 0.55) | 0},${gg},${(gg * 0.35) | 0},0.55)`;
      g.beginPath(); g.moveTo(x, y); g.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); g.stroke();
    }
    T.grass = texFrom(c, true);
  }
  {
    const S = 256; const [c, g] = makeCanvas(S, S);
    g.fillStyle = '#8f8676'; g.fillRect(0, 0, S, S);
    for (let i = 0; i < 14000; i++) {
      const x = rnd() * S, y = rnd() * S, s = 1 + ((rnd() * 3) | 0), v = (70 + rnd() * 140) | 0;
      g.fillStyle = `rgba(${v},${(v * 0.95) | 0},${(v * 0.86) | 0},0.8)`; g.fillRect(x, y, s, s);
    }
    T.gravel = texFrom(c, true);
  }
  {
    const S = 128; const [c, g] = makeCanvas(S, S); const [cb, gb] = makeCanvas(S, S);
    g.fillStyle = '#e8dfd6'; g.fillRect(0, 0, S, S);
    gb.fillStyle = 'rgb(200,200,200)'; gb.fillRect(0, 0, S, S);
    blotches(g, S, 26, rnd, (r) => (r() < 0.5 ? 'rgba(150,120,100,0.22)' : 'rgba(255,248,240,0.25)'));
    for (let i = 0; i < 2600; i++) {
      const x = rnd() * S, y = rnd() * S, s = rnd() < 0.8 ? 1 : 2, v = (120 + rnd() * 120) | 0;
      g.fillStyle = `rgba(${v},${(v * 0.9) | 0},${(v * 0.82) | 0},0.45)`; g.fillRect(x, y, s, s);
      const bv = (110 + rnd() * 140) | 0; gb.fillStyle = `rgb(${bv},${bv},${bv})`; gb.fillRect(x, y, s, s);
    }
    for (let i = 0; i < 60; i++) {
      const x = rnd() * S, y = rnd() * S, r = 0.6 + rnd() * 1.6;
      g.fillStyle = 'rgba(70,50,40,0.55)'; g.beginPath(); g.arc(x, y, r, 0, Math.PI * 2); g.fill();
      gb.fillStyle = 'rgb(40,40,40)'; gb.beginPath(); gb.arc(x, y, r, 0, Math.PI * 2); gb.fill();
    }
    T.brick = texFrom(c, true); T.brickBump = texFrom(cb, false);
  }
  return T;
}
const TEX = makeTextures();

