// Coulomb friction in a sprung hinge so a popped panel stays where the impact left it.
hingeFriction(p) {
  const bd = p.spec.bond, par = p.parent, T = bd.friction * DT;
  const ax = qrot(par.body.rotation(), bd.hinge.axis[0], bd.hinge.axis[1], bd.hinge.axis[2]);
  const wa = p.body.angvel(), wb = par.body.angvel();
  const rel = (wa.x - wb.x) * ax.x + (wa.y - wb.y) * ax.y + (wa.z - wb.z) * ax.z;
  const J = clamp(-rel * p.hingeI, -T, T);
  if (J === 0) return;
  p.body.applyTorqueImpulse({ x: ax.x * J, y: ax.y * J, z: ax.z * J }, true);
  par.body.applyTorqueImpulse({ x: -ax.x * J, y: -ax.y * J, z: -ax.z * J }, true);
}

